#[cfg(test)]mod tests{
 use super::*;use sha2::{Digest,Sha256};use semio_framework_value::{NativeEncodeControl,ValueRefusalKind};
 #[test]fn production_neutral_identity_preimage_sha256_text(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in law["cases"].as_array().unwrap(){let kind:model::DrawingIdentityKind=serde_json::from_value(row["kind"].clone()).unwrap();let parts:Vec<Vec<u8>>=serde_json::from_value(row["parts"].clone()).unwrap();let parts:Vec<&[u8]>=parts.iter().map(Vec::as_slice).collect();let mut callback=|_|true;let mut control=NativeEncodeControl::new(65536,&mut callback);let preimage=binary::encode_identity_preimage(kind,&parts,&mut control).unwrap();assert_eq!(serde_json::to_value(&preimage).unwrap(),row["preimage"]);let oracle:Vec<u8>=Sha256::digest(&preimage).to_vec();assert_eq!(serde_json::to_value(&oracle).unwrap(),row["digest"]);let commitment=binary::commit_identity(kind,&parts,&mut control).unwrap();assert_eq!(commitment.digest.as_slice(),oracle.as_slice());assert_eq!(publication::encode_identity_text(&commitment,&mut control).unwrap(),row["text"].as_str().unwrap());eprintln!("[DEBUG] Draw production identity {} exact counted preimage independent sha2 digest canonical text",row["name"]);}}
 #[test]fn production_identity_exact_ownership_and_cancel(){let mut callback=|_|true;let mut control=NativeEncodeControl::new(12,&mut callback);assert_eq!(binary::encode_identity_preimage(model::DrawingIdentityKind::Layer,&[],&mut control).unwrap_err().kind,ValueRefusalKind::OwnershipLimit);let mut control=NativeEncodeControl::new(13,&mut callback);assert_eq!(binary::encode_identity_preimage(model::DrawingIdentityKind::Layer,&[],&mut control).unwrap().len(),13);let mut cancel=|progress:semio_framework_value::native_encoding::NativeEncodeProgress|progress.completed<269;let mut control=NativeEncodeControl::new(0,&mut cancel);assert_eq!(binary::commit_identity(model::DrawingIdentityKind::Layer,&[&[0;512]],&mut control).unwrap_err().kind,ValueRefusalKind::Canceled);eprintln!("[DEBUG] Draw production identity exact/below ownership and interior cancellation");}
 #[test]fn production_borrowed_spelling_has_no_owned_allocation(){let mut callback=|_|true;let mut control=NativeEncodeControl::new(0,&mut callback);let mut output=[0u8;76];let commitment=model::DrawingIdentityCommitment{kind:model::DrawingIdentityKind::ImageAsset,digest:[0xab;32]};let text=publication::encode_identity_text_into(&commitment,&mut output,&mut control).unwrap();assert_eq!(text.len(),76);assert!(text.starts_with("image-asset-abab"));assert_eq!(control.owned_bytes(),0);eprintln!("[DEBUG] Draw production borrowed spelling exact76 caller-owned stack bytes0 owned allocation");}

 #[test]fn production_identity_records_match_closed_neutral_contract(){use semio_framework_value::{FromValue,NativeDecodeControl};let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in law["recordCases"].as_array().unwrap(){let mut callback=|_|true;let mut control=NativeDecodeControl::new(65536,&mut callback);let value=semio_framework_pack_json::from_json_str_controlled(&row["value"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject,&mut control).unwrap();let accepted=match row["kind"].as_str().unwrap(){"identity"=>model::DrawingIdentity::from_value(value).is_ok(),"assignment"=>model::DrawingIdentityAssignment::from_value(value).is_ok(),"commitment"=>model::DrawingIdentityCommitment::from_value(value).is_ok(),_=>unreachable!()};assert_eq!(accepted,row["accepted"].as_bool().unwrap(),"{row}");}eprintln!("[DEBUG] Draw production identity12 closed first-party record admissions/refusals");}

 #[test]fn production_identity_direct_admission_and_serde_are_sealed(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in law["recordCases"].as_array().unwrap(){if row["kind"]!="identity"{continue;}let accepted=row["accepted"].as_bool().unwrap();assert_eq!(serde_json::from_value::<model::DrawingIdentity>(row["value"].clone()).is_ok(),accepted);if let Some(key)=row["value"]["key"].as_str(){assert_eq!(model::DrawingIdentity::admit(key.into()).is_ok(),!key.is_empty());}}eprintln!("[DEBUG] Draw direct constructor/Serde actual admission matches neutral closed identity contract");}

 #[test]fn production_identity_observes_original_caller_lifetime(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in law["lifetimeCases"].as_array().unwrap(){let original=semio_framework_async::CancelToken::root_now();let child=original.child_now();if row["cancelBefore"].as_bool().unwrap(){original.cancel_now();}let mut checkpoints=0;let at=row["cancelAt"].as_u64();let mut observe=|progress:semio_framework_value::native_encoding::NativeEncodeProgress|{checkpoints+=1;if at.is_some_and(|at|progress.completed>=at as usize){original.cancel_now();}};let result=lifetime::with_identity_control(&child,0,&mut observe,|control|binary::commit_identity(model::DrawingIdentityKind::Layer,&[&[0;512]],control));assert_eq!(result.is_ok(),row["accepted"].as_bool().unwrap());assert!(checkpoints>0);if let Err(error)=result{assert_eq!(error.kind,ValueRefusalKind::Canceled);}else{let mut permissive=|_|true;let mut control=NativeEncodeControl::new(65536,&mut permissive);let bytes=binary::encode_identity_preimage(model::DrawingIdentityKind::Layer,&[&[0;512]],&mut control).unwrap();assert_eq!(result.unwrap().digest.as_slice(),Sha256::digest(bytes).as_slice());}eprintln!("[DEBUG] Draw actual caller/child cancellation {} checkpoints={checkpoints}",row["name"]);}}

 #[test]fn original_io_controls_preserve_cumulative_ownership_and_lifetime(){use semio_framework_value::NativeDecodeControl;let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in law["ioControlCases"].as_array().unwrap(){let cancel=semio_framework_async::CancelToken::root_now();let mut decode_callback=|_|!cancel.is_cancelled_now();let mut encode_callback=|_|!cancel.is_cancelled_now();let mut decode=NativeDecodeControl::new(row["decodeMaximum"].as_u64().unwrap()as usize,&mut decode_callback);let mut encode=NativeEncodeControl::new(row["encodeMaximum"].as_u64().unwrap()as usize,&mut encode_callback);let before_decode:Vec<u8>=serde_json::from_value(row["decodeBefore"].clone()).unwrap();let before_encode:Vec<u8>=serde_json::from_value(row["encodeBefore"].clone()).unwrap();decode.copy_bytes(&before_decode).unwrap();encode.copy_bytes(&before_encode).unwrap();if row["cancelBefore"].as_bool().unwrap(){cancel.cancel_now();}let body:Vec<u8>=serde_json::from_value(row["body"].clone()).unwrap();let mut control=route_control::IoRunControl::new(&mut decode,&mut encode,serde_json::from_value(law["snapshotGrant"].clone()).unwrap());let result=(||{control.checkpoint()?;let input=control.decode()?.copy_bytes(&body)?;let output=control.encode()?.copy_bytes(&input)?;control.checkpoint()?;Ok::<_,semio_framework_value::ValueError>(output)})();assert_eq!(result.is_ok(),row["accepted"].as_bool().unwrap());match result{Ok(output)=>{assert_eq!(output,body);assert_eq!(Sha256::digest(output),Sha256::digest(&body));assert_eq!(control.decode().unwrap().owned_bytes(),row["decodeOwned"].as_u64().unwrap()as usize);assert_eq!(control.encode().unwrap().owned_bytes(),row["encodeOwned"].as_u64().unwrap()as usize)},Err(error)=>assert_eq!(format!("{:?}",error.kind),row["refusal"].as_str().unwrap())}eprintln!("[DEBUG] original native route ledgers/lifetime {}",row["name"]);}}
}
